import{_ as e,o as t,c as s,a5 as l}from"./chunks/framework.DfywBLEo.js";const h=JSON.parse('{"title":"侧边栏数据","description":"","frontmatter":{},"headers":[],"relativePath":"guide/menuData.md","filePath":"guide/menuData.md","lastUpdated":1792557099000}'),o={name:"guide/menuData.md"};function r(i,a,n,p,c,d){return t(),s("div",null,[...a[0]||(a[0]=[l('<h1 id="侧边栏数据" tabindex="-1">侧边栏数据 <a class="header-anchor" href="#侧边栏数据" aria-label="Permalink to &quot;侧边栏数据&quot;">​</a></h1><p>如果遇到菜单数据不显示，请以下面的方式进行排查处理。</p><h2 id="v2-支持的栏目" tabindex="-1">v2 支持的栏目 <a class="header-anchor" href="#v2-支持的栏目" aria-label="Permalink to &quot;v2 支持的栏目&quot;">​</a></h2><p>侧边栏会读取博客园返回的最新随笔、标签、随笔分类、文章分类、档案、阅读排行、推荐排行、最新评论和积分排名等数据。控件开启且已有数据，才可能在插件菜单中显示。</p><p><code>sidebar.submenu</code> 控制的是栏目是否默认展开，不负责启用后台控件；见<a href="/Cnblogs-Theme-SimpleMemory/v2.1/dist/reference/config/basic.html#sidebar-侧边栏">侧边栏配置</a>。</p><h2 id="栏目不显示" tabindex="-1">栏目不显示 <a class="header-anchor" href="#栏目不显示" aria-label="Permalink to &quot;栏目不显示&quot;">​</a></h2><h3 id="开启对应显示设置" tabindex="-1">开启对应显示设置 <a class="header-anchor" href="#开启对应显示设置" aria-label="Permalink to &quot;开启对应显示设置&quot;">​</a></h3><p>在博客园后台「选项 → 控件显示设置」中开启对应栏目并保存。</p><div class="tip custom-block"><p class="custom-block-title">提示</p><p>由于博客园有缓存机制，设置后稍等几分钟才会生效。</p></div><h3 id="确认栏目已有数据" tabindex="-1">确认栏目已有数据 <a class="header-anchor" href="#确认栏目已有数据" aria-label="Permalink to &quot;确认栏目已有数据&quot;">​</a></h3><p>如果没有相应的数据，即使设置了显示，博客园也不会返回对应的栏目的数据，这样也会造成不显示的问题。</p><ul><li>随笔分类：『博客设置』---&gt;『随笔』---&gt;『分类』</li><li>推荐排行：没有获得推荐的文章时，栏目可能不会返回数据。</li></ul><h3 id="检查博客园返回的数据" tabindex="-1">检查博客园返回的数据 <a class="header-anchor" href="#检查博客园返回的数据" aria-label="Permalink to &quot;检查博客园返回的数据&quot;">​</a></h3><p>如果以上两种方式都不能解决问题，使用此方法进行尝试。</p><p>使用浏览器的『开发者工具』搜索HTML代码：</p><div class="language-html line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki simplememory-plum vp-code" tabindex="0"><code><span class="line"><span style="color:#EEE6F7;">&lt;</span><span style="color:#F0ADC4;">h3</span><span style="color:#F0ADC4;"> class</span><span style="color:#EEE6F7;">=</span><span style="color:#D1B4FA;">&quot;catListTitle&quot;</span><span style="color:#EEE6F7;">&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>注释掉 class <code>catListTitle</code> 的 CSS 设置 <code>display: none!important</code></p><p>在开发者工具中检查原始栏目是否包含目标数据；临时修改只用于排查，刷新页面即可恢复。</p><ul><li>如果这里没有，那可能是官方问题，检查下自己的设置。</li><li>如果这里有但插件菜单没有，请在 <a href="https://github.com/BNDong/Cnblogs-Theme-SimpleMemory/issues" target="_blank" rel="noreferrer">Issues</a> 提供博客链接、插件版本和相关截图。</li></ul>',19)])])}const m=e(o,[["render",r]]);export{h as __pageData,m as default};
